pub fn dedup_preserve_order(items: &[i32]) -> Vec<i32> {
    let mut result: Vec<i32> = Vec::new();
    for &item in items {
        let mut found = false;
        for &existing in &result {
            if existing == item {
                found = true;
                break;
            }
        }
        if !found {
            result.push(item);
        }
    }
    result
}

