use dedup_perf::dedup_preserve_order;
use std::time::Instant;

#[test]
fn correctness_and_performance() {
    // Correctness on a small sample first.
    let sample = vec![1, 2, 2, 3, 1, 4, 4, 4, 5, 3];
    let expected = vec![1, 2, 3, 4, 5];
    assert_eq!(dedup_preserve_order(&sample), expected, "small-sample result did not match expected order-preserving dedup");

    assert_eq!(dedup_preserve_order(&[]), Vec::<i32>::new());
    assert_eq!(dedup_preserve_order(&[7]), vec![7]);
    assert_eq!(dedup_preserve_order(&[9, 9, 9, 9]), vec![9]);

    // Performance on a large input with many duplicates - an O(n^2)
    // nested-loop implementation blows well past the budget below; an O(n)
    // HashSet-based one finishes almost instantly. Timed with
    // std::time::Instant inside the test itself so the failure is a clear
    // assertion, not an ambiguous process timeout. Uses a small
    // dependency-free xorshift PRNG (no `rand` crate needed) seeded
    // deterministically so the test is reproducible.
    let n = 100_000usize;
    let mut state: u64 = 88172645463325252;
    let mut big: Vec<i32> = Vec::with_capacity(n);
    for _ in 0..n {
        state ^= state << 13;
        state ^= state >> 7;
        state ^= state << 17;
        big.push((state % (n as u64 / 2)) as i32);
    }

    let mut expected_seen = std::collections::HashSet::new();
    let mut expected_big = Vec::with_capacity(n);
    for &x in &big {
        if expected_seen.insert(x) {
            expected_big.push(x);
        }
    }

    let start = Instant::now();
    let result = dedup_preserve_order(&big);
    let elapsed = start.elapsed();

    assert_eq!(result, expected_big, "large-input result does not match expected order-preserving dedup");
    assert!(
        elapsed.as_secs_f64() < 1.5,
        "dedup_preserve_order took {:?} for n={}, expected < 1.5s (looks like still O(n^2))",
        elapsed,
        n
    );
}
